def wrap(text, width):
    if width < 1:
        raise ValueError
    words = text.split()
    lines = []
    cur = ''
    for word in words:
        i = 0
        while i < len(word):
            chunk = word[i:i+width]
            if cur == '':
                cur = chunk
            else:
                if len(cur) + 1 + len(chunk) <= width:
                    cur = cur + ' ' + chunk
                else:
                    lines.append(cur)
                    cur = chunk
            i += width
    if cur != '':
        lines.append(cur)
    return lines

