tests = [
    ("the quick brown fox", 10, ["the quick", "brown fox"]),
    ("abcdefghij", 4, ["abcd", "efgh", "ij"]),
    ("", 5, []),
    ("a b", 0, "error"),
]

for text, width, expected in tests:
    try:
        result = wrap(text, width)
        if result != expected:
            print("FAIL:", text, width, result, expected)
            raise AssertionError
    except ValueError:
        if expected != "error":
            print("FAIL: expected no error but got ValueError for", text, width)
            raise AssertionError
    except Exception as e:
        print("FAIL: unexpected exception", e)
        raise AssertionError
